"""Standalone, offline annotation UI. Source text is data; labels start blank."""
from __future__ import annotations

import json
from typing import Any, Mapping


def render_context_review(packet: Mapping[str, Any]) -> str:
    if packet.get("kind") != "context_review_pack" or not packet.get("pack_id") or not packet.get("cases"):
        raise ValueError("a nonempty review packet is required.")
    payload = json.dumps(packet, ensure_ascii=False, allow_nan=False)
    # Never let untrusted source text terminate the JSON script element.
    payload = payload.replace("&", "\\u0026").replace("<", "\\u003c").replace(">", "\\u003e")
    return _PAGE.replace("__PACKET_JSON__", payload)


_PAGE = r'''<!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'nonce-local-review'; style-src 'unsafe-inline'; img-src data:; connect-src 'none'; base-uri 'none'; form-action 'none'">
<title>Parcimonia · Atelier de revue</title>
<style>
:root{--paper:#f6f3ea;--ink:#222c29;--muted:#616c65;--line:#d5d9cc;--accent:#296e5a;--amber:#876528}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 'Trebuchet MS',sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer;border:1px solid var(--line);border-radius:3px;padding:8px 13px;background:#fff;color:var(--ink)}button:hover{border-color:var(--accent)}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #99beae;outline-offset:2px}button.primary{background:var(--accent);color:white;border-color:var(--accent)}button:disabled{cursor:default;opacity:.4}header{padding:23px 30px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:20px}.wordmark{font-size:12px;letter-spacing:3px;text-transform:uppercase;color:var(--accent)}h1{font:32px/1.1 Georgia,serif;margin:8px 0}.sub{color:var(--muted);font-size:13px}.toolbar{display:flex;gap:8px;flex-wrap:wrap}.layout{display:grid;grid-template-columns:270px minmax(0,1fr);min-height:calc(100vh - 130px)}aside{background:#23332d;color:#eff3e9;padding:22px 18px;position:sticky;top:0;height:100vh;overflow:auto}.progress{font:32px Georgia,serif;margin:10px 0}.bar{height:4px;background:#4a5b50;margin-bottom:18px}.bar span{display:block;height:100%;background:#b8d4bf;width:0}aside input,aside select{width:100%;margin:5px 0 10px;background:#35473c;color:#fff;border:1px solid #526459;padding:8px}#caseList{display:grid;gap:5px;margin-top:14px}.case-row{text-align:left;background:transparent;color:#f1f3e8;border:1px solid transparent;border-bottom:1px solid #435347;font-size:12px;padding:9px}.case-row.active{background:#e9efdf;color:#25362b;border-color:#e9efdf}.case-row small{display:block;opacity:.75;margin-top:3px}.case-row .dot{float:right;color:#b1d4bc}main{padding:30px 42px 50px;max-width:1220px}.eyebrow{font-size:12px;letter-spacing:1px;text-transform:uppercase;color:var(--accent)}#request{white-space:pre-wrap;font:24px/1.5 Georgia,serif;margin:15px 0 20px;overflow-wrap:anywhere}.section{border-top:1px solid var(--line);padding-top:21px;margin-top:25px}.section h2{font:23px Georgia,serif;margin:0 0 12px}.hint{color:var(--muted);font-size:13px;margin:5px 0 13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px 22px}.field label{display:block;font-size:13px;font-weight:bold;margin-bottom:5px}.field input,.field select,.field textarea{width:100%;padding:9px 10px;border:1px solid #bac2b5;border-radius:3px;background:#fffdf8;color:var(--ink)}textarea{min-height:78px;resize:vertical}.field .mode{margin-bottom:6px}.full{grid-column:1/-1}details{background:#eeeee3;padding:12px 16px;border:1px solid var(--line);margin:10px 0}summary{cursor:pointer;font-weight:bold}.source{padding:12px 0;border-bottom:1px solid #d1d6c7;font-size:12px;overflow-wrap:anywhere}.source p{margin:3px 0}.source button{font-size:11px;padding:4px 8px}.pill{font-size:11px;padding:3px 7px;background:#dce6d9;border-radius:3px;display:inline-block;margin:4px 6px 4px 0}.notice{border-left:3px solid var(--amber);padding:10px 15px;background:#ece8d8;font-size:13px}.footer{display:flex;justify-content:space-between;align-items:center;margin-top:28px;padding-top:18px;border-top:1px solid var(--line);gap:12px}.check{display:flex;align-items:flex-start;gap:9px;font-size:13px}.check input{margin-top:4px}#status{font-size:12px;color:var(--muted);min-height:20px}.pair{display:grid;grid-template-columns:1fr 180px;gap:15px;padding:15px 0;border-bottom:1px solid var(--line)}.pair p{margin:3px 0;font-size:13px}.pair select{padding:7px;max-width:180px}#pairArea{margin-top:15px}.hidden{display:none!important}
@media(max-width:900px){header{padding:20px}.layout{grid-template-columns:190px minmax(0,1fr)}main{padding:25px 22px}.grid{grid-template-columns:1fr}.full{grid-column:auto}.toolbar{justify-content:flex-end}#request{font-size:21px}}
@media(max-width:620px){header{display:block}.toolbar{justify-content:flex-start;margin-top:15px}.layout{display:block}aside{height:auto;position:static;padding:15px}#caseList{max-height:140px;overflow:auto}.progress{font-size:24px}.pair{grid-template-columns:1fr}.footer{flex-wrap:wrap}}
</style></head><body>
<header><div><div class="wordmark">Parcimonia / recherche locale</div><h1>Atelier de revue</h1><div class="sub">Sources retrouvées · annotations indépendantes · aucune prédiction affichée</div></div>
<div class="toolbar"><button id="importBtn">Importer une revue</button><button class="primary" id="exportBtn">Exporter la revue</button><input type="file" id="importFile" accept="application/json,.json" hidden></div></header>
<div class="layout"><aside><div class="sub" style="color:#cedaca">Dossier d’annotation</div><div class="progress" id="progress">0 / 0</div><div class="bar"><span id="progressBar"></span></div><label for="reviewer">Identité de l’annotateur</label><input id="reviewer" placeholder="Nom ou identifiant de revue" autocomplete="off"><label for="search">Rechercher une demande</label><input id="search" placeholder="Mot, projet ou identifiant"><label for="filter">Afficher</label><select id="filter"><option value="all">Toutes les demandes</option><option value="pending">À examiner</option><option value="complete">Revues terminées</option></select><div class="hint" style="color:#cedaca">La revue est enregistrée dans ce navigateur. Exportez le JSON pour conserver une copie.</div><div id="caseList"></div></aside>
<main><div class="eyebrow" id="caseHeading"></div><div id="request"></div><div class="notice">Annotez ce que les sources établissent. Une mention de fichier ne prouve pas qu’il est accessible. « Inconnu » et « aucun » sont deux réponses différentes.</div>
<details><summary id="sourceSummary">Sources de cette demande</summary><div id="sources"></div><div id="sourceGroup" class="hint"></div><label class="check"><input id="sourceReviewed" type="checkbox">J’ai revu la provenance et le groupe de source de ce cas.</label></details>
<section class="section"><h2>1. Langue et opération</h2><div class="grid"><div class="field"><label for="language">Langue constatée</label><select id="language"><option value="">À examiner</option><option value="fr">Français</option><option value="mixed">Français et autre langue</option><option value="other">Autre langue</option><option value="unknown">Non établie</option></select></div><div class="field"><label for="kindMode">Type de tâche</label><select id="kindMode" class="mode"><option value="">À examiner</option><option value="known">Type identifié</option><option value="unknown">Non établi</option></select><input id="taskKind" placeholder="Type de l’opération, selon le référentiel retenu"></div><div class="field"><label for="contractId">Contrat de l’opération, si connu</label><input id="contractId" placeholder="Identifiant du contrat"></div><div class="field"><label for="contractVersion">Version du contrat</label><input id="contractVersion" placeholder="Version"></div><div class="field full"><label for="paraphraseGroup">Groupe de paraphrases, si nécessaire</label><input id="paraphraseGroup" placeholder="Même identifiant pour les demandes apparentées, après revue"><p class="hint">Laissez vide si aucun regroupement supplémentaire n’est établi. La recherche permet de comparer d’autres demandes.</p></div></div></section>
<section class="section"><h2>2. Contexte établi par les sources</h2><p class="hint">Les champs sont des noms de données, séparés par des virgules. Un contexte ancien non conservé reste inconnu.</p><div class="grid" id="labelFields"></div><div class="field full" style="margin-top:16px"><label for="contextNote">Contexte retrouvé ou limite de la capture</label><textarea id="contextNote" placeholder="Précisez ce qui est effectivement visible, ou ce qui n’a pas été conservé."></textarea></div></section>
<section class="section"><h2>3. Justification de l’annotation</h2><div class="grid"><div class="field"><label for="evidenceBasis">Base de l’annotation</label><select id="evidenceBasis"><option value="">À préciser</option><option value="recorded_input">Entrée utilisateur enregistrée</option><option value="verified_outcome">Résultat et vérification indépendants</option><option value="unknown">Source insuffisante</option></select></div><div class="field"><label for="outcomeRef">Référence de résultat, si utilisée</label><input id="outcomeRef" placeholder="Preuve ou relevé indépendant"></div><div class="field full"><label for="rationale">Pourquoi ces labels ?</label><textarea id="rationale" placeholder="Citez les éléments observés et signalez les incertitudes."></textarea></div></div></section>
<section class="section"><h2>Rapprochements à examiner</h2><p class="hint">Ces paires proviennent d’un recouvrement lexical. Elles ne valident ni une paraphrase ni un label. Décidez séparément si elles doivent rester dans le même groupe.</p><div id="pairArea"></div></section>
<div class="footer"><button id="previous">← Précédente</button><label class="check"><input type="checkbox" id="complete">Revue terminée pour ce cas</label><button id="next">Suivante →</button></div><p id="status" role="status" aria-live="polite"></p>
</main></div><script type="application/json" id="packet">__PACKET_JSON__</script>
<script nonce="local-review">
"use strict";
const packet=JSON.parse(document.getElementById('packet').textContent), cases=packet.cases, storageKey='parcimonia.context-review.'+packet.pack_id;
const fieldNames=['provided_fields','required_context','missing_context','unknown_context'];
const labels={provided_fields:'Champs fournis',required_context:'Contexte requis',missing_context:'Contexte manquant',unknown_context:'Contexte inconnu'};
const $=id=>document.getElementById(id);let index=0,state={reviewer:'',annotations:{},pair_decisions:{}};
try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved&&saved.packet_id===packet.pack_id)state={reviewer:saved.reviewer||'',annotations:saved.annotations||{},pair_decisions:saved.pair_decisions||{}}}catch(e){}
function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el}
function empty(){return {language:'',kind_mode:'',task_kind:'',contract_id:'',contract_version:'',paraphrase_group:'',source_reviewed:false,context_note:'',evidence_basis:'',outcome_ref:'',rationale:'',labeler_id:null,complete:false,field_modes:{},field_values:{}}}
function current(){const id=cases[index].case_id;return state.annotations[id]||empty()}
for(const name of fieldNames){const block=node('div',undefined,'field'),label=node('label',labels[name]);label.htmlFor=name+'Mode';block.append(label);const select=node('select');select.id=name+'Mode';select.className='mode';for(const [value,text]of [['','À examiner'],['unknown','Non établi'],['none','Aucun'],['list','Champs identifiés']]){const option=node('option',text);option.value=value;select.append(option)}const input=node('input');input.id=name+'Value';input.placeholder='Noms des champs, séparés par des virgules';block.append(select,input);$('labelFields').append(block)}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({packet_id:packet.pack_id,...state}));$('status').textContent='Brouillon enregistré dans ce navigateur.'}catch(e){$('status').textContent='Enregistrement navigateur indisponible : exportez le JSON pour conserver votre revue.'}}
function getFields(a,name){const mode=a.field_modes[name];return mode==='none'?[]:mode==='list'?a.field_values[name].split(/[\n,]/).map(s=>s.trim()).filter(Boolean):null}
function canComplete(a){if(!state.reviewer.trim()||!a.source_reviewed||!['fr','mixed','other','unknown'].includes(a.language)||!['known','unknown'].includes(a.kind_mode)||!a.rationale.trim()||!['recorded_input','verified_outcome','unknown'].includes(a.evidence_basis))return false;if(a.kind_mode==='known'&&!a.task_kind.trim())return false;if(a.evidence_basis==='verified_outcome'&&!a.outcome_ref.trim())return false;if(Boolean(a.contract_id)!==Boolean(a.contract_version))return false;return fieldNames.every(name=>['unknown','none','list'].includes(a.field_modes[name])&&(a.field_modes[name]!=='list'||getFields(a,name).length>0))}
function readForm(){const a={...current(),language:$('language').value,kind_mode:$('kindMode').value,task_kind:$('taskKind').value.trim(),contract_id:$('contractId').value.trim(),contract_version:$('contractVersion').value.trim(),paraphrase_group:$('paraphraseGroup').value.trim(),source_reviewed:$('sourceReviewed').checked,context_note:$('contextNote').value,evidence_basis:$('evidenceBasis').value,outcome_ref:$('outcomeRef').value.trim(),rationale:$('rationale').value,field_modes:{},field_values:{},complete:false};for(const name of fieldNames){a.field_modes[name]=$(name+'Mode').value;a.field_values[name]=$(name+'Value').value}a.complete=$('complete').checked&&canComplete(a);if(a.complete)a.labeler_id=state.reviewer.trim();state.annotations[cases[index].case_id]=a;return a}
function save(){const attempted=$('complete').checked,a=readForm();$('complete').checked=a.complete;persist();if(attempted&&!a.complete)$('status').textContent='Pour terminer : indiquez l’annotateur, revoyez la source, complétez les choix et la justification.';drawList()}
function drawList(){const completed=cases.filter(c=>state.annotations[c.case_id]?.complete).length;$('progress').textContent=completed+' / '+cases.length;$('progressBar').style.width=(completed/cases.length*100)+'%';$('caseList').replaceChildren();cases.forEach((c,i)=>{const done=state.annotations[c.case_id]?.complete,filter=$('filter').value;if((filter==='pending'&&done)||(filter==='complete'&&!done))return;const search=$('search').value.trim().toLocaleLowerCase();if(search&&!c.text.toLocaleLowerCase().includes(search)&&!c.case_id.includes(search))return;const button=node('button',undefined,'case-row'+(i===index?' active':''));button.append(node('span',String(i+1).padStart(3,'0')+' / '+c.text.slice(0,52)));if(done)button.append(node('span','✓','dot'));button.append(node('small',(c.provenance||[]).length+' source(s) · '+(done?'revue terminée':'à examiner')));button.onclick=()=>{save();index=i;draw()};$('caseList').append(button)})}
function drawPairs(c){$('pairArea').replaceChildren();const pairs=(packet.paraphrase_candidates||[]).filter(p=>p.left===c.case_id||p.right===c.case_id);if(!pairs.length){$('pairArea').append(node('p','Aucun rapprochement lexical proposé pour ce cas.','hint'));return}for(const pair of pairs){const otherId=pair.left===c.case_id?pair.right:pair.left,other=cases.find(row=>row.case_id===otherId),key=[pair.left,pair.right].sort().join(':');const row=node('div',undefined,'pair'),text=node('div');text.append(node('p',other.text),node('small',pair.shared_source_group?'Groupe de source déjà commun.':'Groupes de source distincts.'));const select=node('select');select.setAttribute('aria-label','Décision sur le rapprochement');for(const [value,label]of [['','À examiner'],['same_group','Même groupe'],['different','Distincts'],['unknown','À vérifier']]){const option=node('option',label);option.value=value;select.append(option)}select.value=state.pair_decisions[key]||'';select.onchange=()=>{state.pair_decisions[key]=select.value;persist()};row.append(text,select);$('pairArea').append(row)}}
function draw(){const c=cases[index],a=current();$('caseHeading').textContent='Demande '+(index+1)+' / '+cases.length+' · '+c.case_id.slice(0,12);$('request').textContent=c.text;$('sourceSummary').textContent='Sources retrouvées · '+(c.provenance||[]).length+' occurrence(s)';$('sourceGroup').textContent='Groupe de source : '+(c.source_group||'non établi')+'. Les paraphrases et filiations de conversations restent à vérifier.';$('sources').replaceChildren();for(const source of c.provenance||[]){const el=node('div',undefined,'source');el.append(node('p','Conversation '+source.thread_id));const loc=source.locator;el.append(node('p',source.source_kind==='rollout_jsonl'?'Fichier '+loc.path+' · ligne '+loc.line:'Historique local · tour '+loc.turn_id+' · message '+loc.item_id));el.append(node('p',new Date(source.timestamp_ms).toISOString()));el.append(node('p','Entrée : '+source.recorded_input.content_block_types.join(', ')+' · disponibilité du contexte non établie'));if(source.recorded_input.cwd)el.append(node('p','Espace enregistré : '+source.recorded_input.cwd));$('sources').append(el)}$('language').value=a.language;$('kindMode').value=a.kind_mode;$('taskKind').value=a.task_kind;$('contractId').value=a.contract_id;$('contractVersion').value=a.contract_version;$('paraphraseGroup').value=a.paraphrase_group||'';$('sourceReviewed').checked=a.source_reviewed;$('contextNote').value=a.context_note;$('evidenceBasis').value=a.evidence_basis;$('outcomeRef').value=a.outcome_ref;$('rationale').value=a.rationale;$('complete').checked=a.complete;for(const name of fieldNames){$(name+'Mode').value=a.field_modes[name]||'';$(name+'Value').value=a.field_values[name]||'';$(name+'Value').disabled=a.field_modes[name]!=='list'}$('previous').disabled=index===0;$('next').disabled=index===cases.length-1;drawPairs(c);drawList()}
function exportRecord(){save();const annotations={};for(const c of cases){const a=state.annotations[c.case_id];if(!a)continue;const out={...a,labeler_id:a.labeler_id||null,group_reviewed:a.source_reviewed,source_group:c.source_group,labels:{task_kind:a.kind_mode==='known'?a.task_kind:null},label_origin:'human_review',review_status:a.complete?'completed':'draft'};for(const name of fieldNames)out.labels[name]=getFields(a,name);annotations[c.case_id]=out}return {schema_version:1,kind:'context_human_review',parent_pack_id:packet.parent_pack_id||null,packet_id:packet.pack_id,reviewer_id:state.reviewer.trim()||null,annotations,pair_decisions:state.pair_decisions,independent_labels_established:false,claim_allowed:false,auto_act_allowed:false}}
function download(record){const url=URL.createObjectURL(new Blob([JSON.stringify(record,null,2)],{type:'application/json'})),a=node('a');a.href=url;a.download='context-review-'+packet.pack_id.slice(0,12)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='Revue exportée. Les annotations humaines restent distinctes des prédictions.'}
function importReview(data){if(data.kind!=='context_human_review'||data.packet_id!==packet.pack_id||!data.annotations||typeof data.annotations!=='object')throw new Error('Le fichier ne correspond pas à ce dossier.');const allowed=new Set(cases.map(c=>c.case_id));for(const id of Object.keys(data.annotations))if(!allowed.has(id))throw new Error('Le fichier contient une demande étrangère.');const next={reviewer:typeof data.reviewer_id==='string'?data.reviewer_id:'',annotations:{},pair_decisions:{}};for(const [id,raw]of Object.entries(data.annotations)){const a=empty();for(const key of ['language','kind_mode','task_kind','contract_id','contract_version','paraphrase_group','context_note','evidence_basis','outcome_ref','rationale'])a[key]=typeof raw[key]==='string'?raw[key]:'';a.labeler_id=typeof raw.labeler_id==='string'?raw.labeler_id:null;a.source_reviewed=raw.source_reviewed===true;a.complete=raw.complete===true;for(const name of fieldNames){a.field_modes[name]=typeof raw.field_modes?.[name]==='string'?raw.field_modes[name]:'';a.field_values[name]=typeof raw.field_values?.[name]==='string'?raw.field_values[name]:''}next.annotations[id]=a}const validPairs=new Set((packet.paraphrase_candidates||[]).map(p=>[p.left,p.right].sort().join(':')));for(const [key,value]of Object.entries(data.pair_decisions||{}))if(validPairs.has(key)&&['','same_group','different','unknown'].includes(value))next.pair_decisions[key]=value;state=next;for(const a of Object.values(state.annotations))a.complete=a.complete&&canComplete(a);$('reviewer').value=state.reviewer;persist();draw()}
$('reviewer').value=state.reviewer;$('reviewer').oninput=()=>{state.reviewer=$('reviewer').value;save()};$('filter').onchange=drawList;$('search').oninput=drawList;$('previous').onclick=()=>{save();if(index>0){index--;draw();window.scrollTo(0,0)}};$('next').onclick=()=>{save();if(index<cases.length-1){index++;draw();window.scrollTo(0,0)}};$('exportBtn').onclick=()=>download(exportRecord());$('importBtn').onclick=()=>$('importFile').click();$('importFile').onchange=async()=>{try{importReview(JSON.parse(await $('importFile').files[0].text()));$('status').textContent='Revue importée.'}catch(e){$('status').textContent='Import refusé : '+e.message}};
for(const id of ['language','kindMode','taskKind','contractId','contractVersion','paraphraseGroup','sourceReviewed','contextNote','evidenceBasis','outcomeRef','rationale','complete',...fieldNames.flatMap(n=>[n+'Mode',n+'Value'])])$(id).addEventListener('change',()=>{save();for(const n of fieldNames)$(n+'Value').disabled=$(n+'Mode').value!=='list'});draw();
</script></body></html>'''
